import{_ as h,o as t,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"&quot;Làm nhiều bài ≠ học tốt&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"mental-models/lam-nhieu-bai.md","filePath":"mental-models/lam-nhieu-bai.md"}'),c={name:"mental-models/lam-nhieu-bai.md"};function o(g,n,m,r,u,e){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="quot-lam-nhieu-bai-hoc-tot-quot" tabindex="-1">&quot;Làm nhiều bài ≠ học tốt&quot; <a class="header-anchor" href="#quot-lam-nhieu-bai-hoc-tot-quot" aria-label="Permalink to &quot;&amp;quot;Làm nhiều bài ≠ học tốt&amp;quot;&quot;">​</a></h1><p>Trên trang này# &quot;Làm nhiều bài ≠ học tốt&quot; <a href="#lam-nhieu-bai-hoc-tot">​</a> Số lượng bài tập là thứ dễ đo nhất trong việc học, nên nó trở thành thước đo mặc định. Nhưng bài thứ hai mươi cùng một dạng gần như không dạy được gì — nó chỉ tốn thêm một giờ của một đứa trẻ.</p><h2 id="bai-tap-day-đuoc-gi-va-khong-day-đuoc-gi-​" tabindex="-1">Bài tập dạy được gì và không dạy được gì <a href="#bai-tap-day-đuoc-gi-va-khong-day-đuoc-gi">​</a> <a class="header-anchor" href="#bai-tap-day-đuoc-gi-va-khong-day-đuoc-gi-​" aria-label="Permalink to &quot;Bài tập dạy được gì và không dạy được gì [​](#bai-tap-day-đuoc-gi-va-khong-day-đuoc-gi)&quot;">​</a></h2><p>Một bài tập tạo ra việc học khi nó <strong>nằm ở rìa khả năng hiện tại</strong> của learner: khó vừa đủ để phải nghĩ, dễ vừa đủ để có cơ hội làm được. Bài quá dễ không dạy gì — chỉ xác nhận điều đã biết. Bài quá khó cũng không dạy gì — learner đoán, bỏ, hoặc chép đáp án. Cả hai đều tiêu thời gian như nhau. Vấn đề: trong một tập 30 bài giao chung cho cả lớp, thường chỉ 5–8 bài nằm đúng vùng đó với một learner cụ thể. Phần còn lại là thời gian bị đốt.</p><h2 id="đuong-cong-loi-ich-giam-dan-​" tabindex="-1">Đường cong lợi ích giảm dần <a href="#đuong-cong-loi-ich-giam-dan">​</a> <a class="header-anchor" href="#đuong-cong-loi-ich-giam-dan-​" aria-label="Permalink to &quot;Đường cong lợi ích giảm dần [​](#đuong-cong-loi-ich-giam-dan)&quot;">​</a></h2><p>Bài sốHọc được gì1–3Nhiều — đang hình thành cách làm4–8Khá — củng cố, phát hiện chỗ hổng9–15Ít dần — chủ yếu tăng tốc độ16–30Gần như không — trừ khi đổi dạngSau bài thứ 8-10 cùng dạng, thứ đang tăng lên là <strong>tốc độ và sự thành thục</strong>, không phải hiểu biết. Điều đó có giá trị riêng của nó — nhưng nếu learner vẫn chưa hiểu nguyên tắc, bài thứ 25 cũng không sửa được. Cách phá vỡ đường cong này không phải làm thêm bài, mà là <strong>đổi dạng bài</strong>. Năm bài ở năm ngữ cảnh khác nhau dạy nhiều hơn hai mươi bài cùng khuôn.</p><h2 id="vi-sao-them-bai-la-phan-xa-tu-nhien-​" tabindex="-1">Vì sao &quot;thêm bài&quot; là phản xạ tự nhiên <a href="#vi-sao-them-bai-la-phan-xa-tu-nhien">​</a> <a class="header-anchor" href="#vi-sao-them-bai-la-phan-xa-tu-nhien-​" aria-label="Permalink to &quot;Vì sao &quot;thêm bài&quot; là phản xạ tự nhiên [​](#vi-sao-them-bai-la-phan-xa-tu-nhien)&quot;">​</a></h2><p>Ba lý do, đều dễ hiểu: <strong>Nó đo được.</strong> &quot;Con làm 40 bài&quot; là một câu nói được. &quot;Con hiểu sâu hơn về tỷ lệ&quot; thì không. <strong>Nó cho cảm giác kiểm soát.</strong> Khi con học kém và bạn không biết vì sao, giao thêm bài là việc duy nhất bạn làm được ngay. <strong>Nó từng có tác dụng.</strong> Với những học sinh đã có nền và chỉ cần thành thục, thêm bài đúng là có tác dụng. Vấn đề là nó được áp dụng cả cho những trường hợp hoàn toàn khác.</p><h2 id="khi-them-bai-la-sai-hoan-toan-​" tabindex="-1">Khi thêm bài là sai hoàn toàn <a href="#khi-them-bai-la-sai-hoan-toan">​</a> <a class="header-anchor" href="#khi-them-bai-la-sai-hoan-toan-​" aria-label="Permalink to &quot;Khi thêm bài là sai hoàn toàn [​](#khi-them-bai-la-sai-hoan-toan)&quot;">​</a></h2><p><strong>Khi learner chưa hiểu.</strong> Giao thêm bài cho người chưa hiểu tạo ra thêm lần thất bại, không tạo ra hiểu biết. Việc cần làm là quay lại giải thích và bài mẫu. <strong>Khi lỗ hổng nằm ở kiến thức nền.</strong> Con sai bài lượng giác vì yếu biến đổi đại số cơ bản. Hai mươi bài lượng giác nữa không chạm được vào nguyên nhân — mà nguyên nhân thì nằm ở hai lớp trước. <strong>Khi learner đã mệt.</strong> Sau một ngưỡng nhất định, thêm bài chỉ tạo ra dữ liệu nhiễu: đúng-sai lúc này phản ánh mức mệt nhiều hơn phản ánh hiểu biết. <strong>Khi phần đó đã vững.</strong> Củng cố thứ đã chắc trong khi có chỗ khác đang yếu là dùng sai thời gian — và thời gian của một đứa trẻ là tài nguyên hữu hạn nhất trong toàn bộ câu chuyện này.</p><h2 id="nemo12-lam-gi-thay-vi-them-bai-​" tabindex="-1">Nemo12 làm gì thay vì thêm bài <a href="#nemo12-lam-gi-thay-vi-them-bai">​</a> <a class="header-anchor" href="#nemo12-lam-gi-thay-vi-them-bai-​" aria-label="Permalink to &quot;Nemo12 làm gì thay vì thêm bài [​](#nemo12-lam-gi-thay-vi-them-bai)&quot;">​</a></h2><p><strong>Sai nhiều lần thì đổi cách, không tăng số lượng.</strong> Đây là quy tắc cứng: khi learner làm sai lặp lại, hệ thống hạ độ khó, thêm giàn giáo, quay về bài mẫu — hoặc đi tìm lỗ hổng nền. <strong>Không bao giờ</strong> ném thêm 20 bài cùng dạng. <strong>Bài đo dừng khi đủ chắc chắn.</strong> Không có &quot;bài kiểm tra 40 câu&quot; cố định. Nếu 6 câu đã đủ để kết luận, dừng ở 6. <strong>Chủ động phát hiện học thừa.</strong> Hệ thống nhận ra khi learner đang luyện lại thứ đã rất chắc, và chuyển hướng — kể cả khi learner vẫn muốn làm tiếp. <strong>Chuyển hướng khi lợi ích giảm.</strong> Khi mỗi phút thêm ở đây chỉ còn đẩy được rất ít, trong khi chỗ khác đang yếu hơn nhiều, hệ thống chuyển. <a href="/learning/hoc-ky">Xem giới hạn của học kỹ →</a></p><h2 id="thay-thuoc-đo-​" tabindex="-1">Thay thước đo <a href="#thay-thuoc-đo">​</a> <a class="header-anchor" href="#thay-thuoc-đo-​" aria-label="Permalink to &quot;Thay thước đo [​](#thay-thuoc-đo)&quot;">​</a></h2><p>Thước đo cũHôm nay con làm bao nhiêu bài?Con học mấy tiếng?Đã hết bài tập chưa? Thước đo tốt hơnHôm nay con hiểu ra điều gì mà hôm qua chưa hiểu?Có bài nào lúc đầu không làm được mà sau làm được không?Chỗ nào con vẫn thấy mơ hồ? Ba câu bên phải khó trả lời hơn — và chính vì thế chúng có ích. Một đứa trẻ trả lời được ba câu đó là một đứa trẻ đang theo dõi việc học của chính mình. Một cảnh báo thực tế Nếu con đang học 4 tiếng mỗi tối mà không tiến bộ, thêm tiếng thứ năm gần như chắc chắn không phải câu trả lời. Nhiều khả năng thời gian đang được đổ vào sai chỗ — và chỗ đúng thường nằm ở một kiến thức nền cách đó một hai năm. Việc học không đo bằng số bài đã làm. Nó đo bằng khoảng cách giữa thứ learner làm được hôm nay và thứ làm được hôm qua. <a href="/mental-models/test-khong-phan-xet">Test không phải để phán xét →</a></p>',14)])])}const b=h(c,[["render",o]]);export{s as __pageData,b as default};
